{
  "items": [
    {
      "title": "Flash Eurobarometer 313 (User Language Preferences Online)",
      "url_or_doi": "https://doi.org/10.4232/1.10730",
      "justification": "Official dataset archived by GESIS – Leibniz Institute for the Social Sciences. This is an exact title match, identified by study number ZA5473, version 1.0.0, published in 2011. The dataset examines language preferences and multilingual internet usage among European internet users aged 15 and older. It contains 13,752 interviews conducted across 27 EU member states between January 28 and February 1, 2011. This DOI provides the permanent reference to the dataset."
    },
    {
      "title": "Flash Eurobarometer 313 (User Language Preferences Online) – GESIS Data Catalogue",
      "url_or_doi": "https://search.gesis.org/research_data/ZA5473?lang=en",
      "justification": "Official GESIS dataset landing page containing detailed metadata, study documentation, methodology, sampling information, and dataset access options. The record identifies the European Commission as the principal investigator and GESIS as the data publisher. It corresponds directly to the requested dataset and provides information about its 107 variables."
    },
    {
      "title": "Flash Eurobarometer 313: User Language Preferences Online – European Data Portal",
      "url_or_doi": "https://data.europa.eu/data/datasets/s880_313?locale=en",
      "justification": "Official European Union open data catalogue entry for Flash Eurobarometer 313. It describes the survey's investigation of European internet users' language preferences and provides access to associated statistical results and data tables. This is an authoritative alternative source maintained through the EU's open data infrastructure."
    },
    {
      "title": "Flash Eurobarometer 313 (User Language Preferences Online) – B2FIND",
      "url_or_doi": "https://b2find.eudat.eu/dataset/96aaef5d-a82a-525f-b093-6606d5e4dbfd",
      "justification": "Dataset metadata record in the B2FIND research data discovery service. It identifies the same GESIS dataset through DOI 10.4232/1.10730 and provides information about its research topics, geographical coverage, collection methodology, publisher, and access rights. This is an additional discovery portal for the requested dataset."
    }
  ]
}
